 glyphs={'Source':'<path d="M12 5h18l8 8v30H12zM30 5v10h8M19 23h12M19 30h12M19 37h8"/>','Rules':'<path d="M8 10h32M8 24h32M8 38h32"/><circle cx="18" cy="10" r="4" fill="white"/><circle cx="31" cy="24" r="4" fill="white"/><circle cx="15" cy="38" r="4" fill="white"/>','Lines':'<path d="M5 8h38v32H5zM5 18h38M5 29h38M19 8v32"/>','Events':'<path d="M12 5v38M12 11h26M12 24h19M12 37h26"/><circle cx="12" cy="11" r="4" fill="white"/><circle cx="12" cy="24" r="4" fill="white"/><circle cx="12" cy="37" r="4" fill="white"/>','Review':'<circle cx="22" cy="13" r="7"/><path d="M8 41v-7c0-10 28-10 28 0v7M29 28l5 5 9-9"/>'}
 svg='<svg xmlns="http://www.w3.org/2000/svg" width="720" height="680" viewBox="0 0 720 680"><title>Fictional order source to deterministic review</title><desc>Original JSON source is admitted and projected by CPU rules. The same role-filtered facts appear as schedule lines and source events. Human local review binds the exact source revision, policy, role, block and view. No ERP write or live model branch.</desc><defs><pattern id="dots" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#374354"/></pattern><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9" fill="#a7b5c7"/></marker></defs><rect width="720" height="680" fill="#171e2a"/><rect width="720" height="680" fill="url(#dots)"/>'
 for d in ['M235 95C300 55 350 65 415 95','M480 195C480 245 190 210 190 275','M480 195C480 225 530 230 530 275','M190 425C190 475 360 460 360 505','M530 425C530 475 360 460 360 505']:svg+=f'<path d="{d}" stroke="#a7b5c7" stroke-width="3" fill="none" marker-end="url(#arrow)"/>'
 for name,x,y in [('Source',170,40),('Rules',480,40),('Lines',190,275),('Events',530,275),('Review',360,505)]:svg+=f'<rect x="{x-65}" y="{y}" width="130" height="110" rx="20" fill="white" stroke="#b8c6da" stroke-width="2"/><svg x="{x-36}" y="{y+19}" width="72" height="72" viewBox="0 0 48 48"><g fill="none" stroke="#245b7c" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round">{glyphs[name]}</g></svg><text x="{x}" y="{y+148}" fill="#dbe5f2" font-family="sans-serif" font-size="36" text-anchor="middle">{name}</text>'
 svg+='</svg>';(ROOT/'docs/architecture.svg').write_text(svg+'\n')
 async with async_playwright()as p:
  browser=await p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox','--disable-gpu']);page=await browser.new_page(viewport={'width':720,'height':680});await page.goto((ROOT/'docs/architecture.svg').as_uri());await page.locator('svg').first.screenshot(path=str(ROOT/'docs/architecture.png'))
  for width in [360,390]:
   await page.goto('about:blank');await page.set_viewport_size({'width':width,'height':750});await page.set_content(f'<body style="margin:0"><img src="data:image/svg+xml;base64,{base64.b64encode(svg.encode()).decode()}" style="width:100%" alt="Original source rules lines events review graph"></body>');await page.locator('img').screenshot(path=str(ROOT/f'private/diagram-{width}.png'))
  await browser.close()
 (ROOT/'docs/asset-provenance.json').write_text(json.dumps({'license':'MIT','assets':'Original geometric generic process glyphs; not technology or vendor logos','style':'User-approved dark dotted background, rounded white cards, curved arrows, short names below glyphs. No reference image pixels copied.','reference_transfer':'Earlier style approval retained; no new Library materialization or credential forwarding','topology':'source JSON -> CPU admission/rules -> parallel role-filtered lines/events -> human local review receipt','resource_embedding':'Native inline SVG paths; no external resources','fit':'48x48 square viewBox fitted explicitly to72x72; ratio1 preserved','narrow_label_px_at_360':18,'files':[{'path':'docs/'+n,'sha256':hashlib.sha256((ROOT/'docs'/n).read_bytes()).hexdigest()}for n in ['architecture.svg','architecture.png']]},indent=2)+'\n')
